exp_rfm_scores as (

    select
        exp_recency2.customer_id as customer_id,
        exp_recency2.customer_name as customer_name,
        exp_recency2.count_lifetime_orders as count_lifetime_orders,
        exp_recency2.first_ordered_at as first_ordered_at,
        exp_recency2.last_ordered_at as last_ordered_at,
        exp_recency2.lifetime_spend as lifetime_spend,
