        exp_recency2.customer_type as customer_type,
        exp_recency2.recency_days as recency_days,
        (case when exp_recency2.recency_days <= 30 then 3 else case when exp_recency2.recency_days <= 90 then 2 else 1 end end) as r_score,
        (case when exp_recency2.count_lifetime_orders >= 5 then 3 else case when exp_recency2.count_lifetime_orders >= 2 then 2 else 1 end end) as f_score,
        (case when exp_recency2.lifetime_spend >= 200 then 3 else case when exp_recency2.lifetime_spend >= 50 then 2 else 1 end end) as m_score,
        (case when exp_recency2.recency_days <= 30 then 3 else case when exp_recency2.recency_days <= 90 then 2 else 1 end end) * 100 + (case when exp_recency2.count_lifetime_orders >= 5 then 3 else case when exp_recency2.count_lifetime_orders >= 2 then 2 else 1 end end) * 10 + (case when exp_recency2.lifetime_spend >= 200 then 3 else case when exp_recency2.lifetime_spend >= 50 then 2 else 1 end end) as rfm_score
