        exp_rfm_scores.f_score as f_score,
        exp_rfm_scores.m_score as m_score,
        exp_rfm_scores.rfm_score as rfm_score,
        (case when exp_rfm_scores.count_lifetime_orders = 0 then 'PROSPECT' else case when exp_rfm_scores.rfm_score = 333 then 'CHAMPION' else case when exp_rfm_scores.r_score = 3 and exp_rfm_scores.f_score >= 2 and exp_rfm_scores.m_score >= 2 then 'LOYAL' else case when exp_rfm_scores.r_score = 1 and exp_rfm_scores.f_score >= 2 then 'AT_RISK' else 'STANDARD' end end end end) as rfm_segment
    from exp_rfm_scores

)

select
    cast(exp_rfm_segment.customer_id as varchar) as customer_id,
    cast(exp_rfm_segment.customer_name as varchar) as customer_name,
    cast(exp_rfm_segment.count_lifetime_orders as double) as count_lifetime_orders,
    cast(exp_rfm_segment.first_ordered_at as timestamp) as first_ordered_at,
    cast(exp_rfm_segment.last_ordered_at as timestamp) as last_ordered_at,
    cast(exp_rfm_segment.lifetime_spend as decimal(12,2)) as lifetime_spend_pretax,
    cast(exp_rfm_segment.lifetime_spend_pretax as decimal(12,2)) as lifetime_tax_paid,
    cast(exp_rfm_segment.lifetime_tax_paid as decimal(12,2)) as lifetime_spend,
    cast(exp_rfm_segment.lifetime_cogs as decimal(12,2)) as lifetime_cogs,
