    cast(exp_rfm_segment.avg_order_value as decimal(12,2)) as avg_order_value,
    cast(exp_rfm_segment.high_value_orders as double) as high_value_orders,
    cast(exp_rfm_segment.customer_type as varchar) as customer_type,
    cast(exp_rfm_segment.recency_days as double) as recency_days,
    cast(exp_rfm_segment.r_score as decimal(1,0)) as r_score,
    cast(exp_rfm_segment.f_score as decimal(1,0)) as f_score,
    cast(exp_rfm_segment.m_score as decimal(1,0)) as m_score,
    cast(exp_rfm_segment.rfm_score as double) as rfm_score,
    cast(exp_rfm_segment.rfm_segment as varchar) as rfm_segment
from exp_rfm_segment
